solutionCode:
sealed class SensorReading {
    class Connected(val value: Double) : SensorReading()
    object Disconnected : SensorReading()
    class Error(val message: String) : SensorReading()
}

fun report(reading: SensorReading): String {
    return when (reading) {
        is SensorReading.Connected -> "Reading: ${reading.value}"
        is SensorReading.Disconnected -> "No sensor connected"
        is SensorReading.Error -> "Sensor error: ${reading.message}"
    }
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testConnected() {
        Assert.assertEquals("Reading: 42.5", report(SensorReading.Connected(42.5)))
    }

    @Test
    fun testDisconnected() {
        Assert.assertEquals("No sensor connected", report(SensorReading.Disconnected))
    }

    @Test
    fun testError() {
        Assert.assertEquals("Sensor error: Timeout", report(SensorReading.Error("Timeout")))
    }

    @Test
    fun testConnectedZero() {
        Assert.assertEquals("Reading: 0.0", report(SensorReading.Connected(0.0)))
    }

    @Test
    fun testErrorDifferentMessage() {
        Assert.assertEquals("Sensor error: Out of range", report(SensorReading.Error("Out of range")))
    }
}
